// RegisterIntents adds the spec-declared intent tools to the MCP server.
// This is called from RegisterTools when MCP.Intents is non-empty.
func RegisterIntents(s *server.MCPServer) {
	s.AddTool(
		mcplib.NewTool("fetch_recording_with_transcript",
			mcplib.WithDescription("Get a recording's full detail plus its speaker-diarized transcript and AI summary in one call."),
			mcplib.WithString("id", mcplib.Required(), mcplib.Description("Plaud file_id of the recording")),
		),
		handleFetchRecordingWithTranscript,
	)
	s.AddTool(
		mcplib.NewTool("list_recent_recordings",
			mcplib.WithDescription("List recordings within a time window, sorted by start_time descending. Useful for 'show me what I've recorded recently'."),
			mcplib.WithNumber("limit", mcplib.Description("Max recordings to return (default 50)")),
		),
		handleListRecentRecordings,
	)
	s.AddTool(
		mcplib.NewTool("get_shareable_link_for_recording",
			mcplib.WithDescription("Create a public shareable link for one recording with permission flags."),
			mcplib.WithString("id", mcplib.Required(), mcplib.Description("Recording ID")),
		),
		handleGetShareableLinkForRecording,
	)
	s.AddTool(
		mcplib.NewTool("export_recording_as_document",
			mcplib.WithDescription("Export a recording's transcript or summary as DOCX/PDF/TXT/MD."),
			mcplib.WithString("file_id", mcplib.Required(), mcplib.Description("Recording ID")),
			mcplib.WithString("prompt_type", mcplib.Required(), mcplib.Description("Either 'trans' or 'summary'")),
			mcplib.WithString("to_format", mcplib.Required(), mcplib.Description("docx, pdf, txt, or md")),
		),
		handleExportRecordingAsDocument,
	)
	s.AddTool(
		mcplib.NewTool("trash_recordings_batch",
			mcplib.WithDescription("Move multiple recordings to trash in one call. Returns the batch result with counts."),
			mcplib.WithString("ids", mcplib.Required(), mcplib.Description("JSON array of recording IDs to trash")),
		),
		handleTrashRecordingsBatch,
	)
	s.AddTool(
		mcplib.NewTool("get_recording_audio_url",
			mcplib.WithDescription("Get a pre-signed 24-hour audio download URL for one recording. Optional opus flag for OGG."),
			mcplib.WithString("id", mcplib.Required(), mcplib.Description("Recording ID")),
			mcplib.WithBoolean("is_opus", mcplib.Description("Return OGG/Opus instead of MP3")),
		),
		handleGetRecordingAudioUrl,
	)
	s.AddTool(
		mcplib.NewTool("enrich_recordings_by_ids",
			mcplib.WithDescription("Fetch full transcripts + AI content for a batch of recordings in a single call. More efficient than per-recording fetches."),
			mcplib.WithString("ids", mcplib.Required(), mcplib.Description("JSON array of recording IDs")),
		),
		handleEnrichRecordingsByIds,
	)
}

